'use client';
import { Fragment, useEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { enter, Swap, Tip, useGrow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './file-explorer.css';

/** How the agent changed a file: modified, added or deleted */
export type FileExplorerStatus = 'M' | 'A' | 'D';

/** A file, or a folder when it has children */
export interface FileExplorerNode {
  name: string;
  /** Marks a file the agent changed. Folders with a changed file inside get a dot */
  status?: FileExplorerStatus;
  children?: FileExplorerNode[];
}

export interface FileExplorerProps {
  tree: FileExplorerNode[];
  /** Paths of the open folders, like "src/components". Leave it out to let the folders open and close by themselves */
  open?: string[];
  defaultOpen?: string[];
  onOpenChange?: (paths: string[]) => void;
  /** Path of the selected file */
  selected?: string;
  defaultSelected?: string;
  onSelectedChange?: (path: string) => void;
  /** The filter text */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  /** Shows only the files the agent changed */
  onlyChanged?: boolean;
  defaultOnlyChanged?: boolean;
  onOnlyChangedChange?: (only: boolean) => void;
  /** The footer while only changed files show. Defaults to "6 files changed by the agent" */
  summary?: (changed: number) => string;
  /** The icon for a file. Defaults to one picked by its extension */
  fileIcon?: (name: string) => IconName;
  placeholder?: string;
  className?: string;
}

const WORD: Record<FileExplorerStatus, string> = { M: 'Modified', A: 'Added', D: 'Deleted' };
const changed = (n: FileExplorerNode): boolean => !!n.status || !!n.children?.some(changed);
const count = (ns: FileExplorerNode[]): number => ns.reduce((s, n) => s + (n.children ? count(n.children) : n.status ? 1 : 0), 0);
const matches = (n: FileExplorerNode, q: string): boolean => !q || n.name.toLowerCase().includes(q) || !!n.children?.some(k => matches(k, q));
const iconFor = (name: string): IconName => /\.tsx$/.test(name) ? 'code' : /\.css$/.test(name) ? 'palette' : /\.png|\.svg$/.test(name) ? 'image' : 'file-text';

/** Project files in a tree you can filter, with the ones the agent touched marked. */
export function FileExplorer({
  tree, open, defaultOpen = [], onOpenChange, selected, defaultSelected = '', onSelectedChange, query, defaultQuery = '', onQueryChange,
  onlyChanged, defaultOnlyChanged = false, onOnlyChangedChange, summary = n => `${n} files changed by the agent`, fileIcon = iconFor,
  placeholder = 'Filter files', className
}: FileExplorerProps) {
  const [opened, setOpened] = useControllable(open, defaultOpen, onOpenChange);
  const [sel, setSel] = useControllable(selected, defaultSelected, onSelectedChange);
  const [text, setText] = useControllable(query, defaultQuery, onQueryChange);
  const [only, setOnly] = useControllable(onlyChanged, defaultOnlyChanged, onOnlyChangedChange);
  const [foot, setFoot] = useState<'selected' | 'summary'>(only ? 'summary' : 'selected');
  const q = text.trim().toLowerCase();
  // the card grows as folders open and shrinks as they close or the filter narrows (as grow() on the site)
  const [root, inner] = useGrow();
  // while there is more of the tree below, its last row fades at the edge instead of being cut off (a row's entrance lifts it
  // a few pixels, so less than half a row more doesn't count)
  const treeRef = useRef<HTMLDivElement>(null), [more, setMore] = useState(false);
  // Clean's one hover: a highlight that glides from row to row; the picked file keeps its own fill
  useHoverGlide(treeRef, '.dm-fxp-n', { keep: '.dm-sel' });
  useEffect(() => {
    const t = treeRef.current; if (!t) return;
    const edge = () => setMore(t.scrollTop + t.clientHeight < t.scrollHeight - 12);
    const ro = new ResizeObserver(edge); ro.observe(t); edge();
    t.addEventListener('scroll', edge, { passive: true }); t.addEventListener('transitionend', edge); t.addEventListener('animationend', edge);
    return () => { ro.disconnect(); t.removeEventListener('scroll', edge); t.removeEventListener('transitionend', edge); t.removeEventListener('animationend', edge); };
  }, []);

  // the tree is drawn afresh when the filter starts or ends and when only changed files show, as on the site;
  // it staggers in when it first appears and when that switch flips
  const [round, setRound] = useState({ only, q: !!q, n: 0, stagger: true });
  if (round.only !== only || round.q !== !!q) setRound({ only, q: !!q, n: round.n + 1, stagger: round.only !== only });

  let index = 0;
  const branch = (nodes: FileExplorerNode[], path: string, depth: number): ReactNode[] => nodes
    .filter(k => matches(k, q) && (!only || changed(k)))
    .map(k => {
      const p = path ? path + '/' + k.name : k.name, folder = !!k.children, isOpen = folder && (opened.includes(p) || !!q || only);
      const anim = round.stagger ? enter(index++ * 25) : undefined;
      const row = (
        <button type="button" role="treeitem" aria-expanded={folder ? isOpen : undefined} aria-selected={folder ? undefined : p === sel}
          className={cx('dm-fxp-n', isOpen && 'dm-open', p === sel && 'dm-sel', k.status && 'dm-' + k.status, anim?.className)}
          style={{ paddingLeft: 9 + depth * 14, ...anim?.style }}
          onClick={() => {
            if (folder) setOpened(opened.includes(p) ? opened.filter(x => x !== p) : [...opened, p]);
            else { setSel(p); setFoot('selected'); }
          }}>
          <span className="dm-cv">{folder && <Icon name="chev-r" size="xs" />}</span>
          <span className="dm-ic"><Icon name={folder ? 'folder' : fileIcon(k.name)} size="xs" /></span>
          <span className="dm-nm">{k.name}</span>
          {k.status ? <span className={cx('dm-bd', 'dm-' + k.status)} aria-label={WORD[k.status]}>{k.status}</span> : folder && changed(k) ? <span className="dm-ag" aria-hidden="true" /> : null}
        </button>
      );
      return (
        <Fragment key={p}>
          {row}
          {folder && <div className={cx('dm-fxp-k', !isOpen && 'dm-shut')} role="group" inert={!isOpen}><div>{branch(k.children!, p, depth + 1)}</div></div>}
        </Fragment>
      );
    });

  const rows = branch(tree, '', 0);
  return (
    <div data-dm="" ref={root} className={cx('dm-fxp dm-panel dm-growing', className)}>
      <div ref={inner} className="dm-grow">
        <div className="dm-fxp-h">
          <div className="dm-fxp-s">
            <Icon name="search" size="xs" />
            <input placeholder={placeholder} aria-label="Filter files" spellCheck={false} value={text} onChange={e => setText(e.target.value)} />
          </div>
          <Tip label="Only changed files">
            <button type="button" className="dm-ib dm-fxp-ch" aria-label="Only changed" aria-pressed={only}
              onClick={() => { setOnly(!only); setFoot(only ? 'selected' : 'summary'); }}><Icon name="filter" size="xs" /></button>
          </Tip>
        </div>
        <div ref={treeRef} className={cx('dm-fxp-tree', more && 'dm-more')} role="tree" aria-label="Files" hidden={!rows.length}><Fragment key={round.n}>{rows}</Fragment></div>
        {/* nothing matches the filter: the empty state, and Clear filter brings the tree back */}
        {!rows.length && (
          <div className="dm-fxp-em"><span className="dm-fxp-em-art" aria-hidden="true" /><b>No matching files</b><span>Nothing in the project is called “{text.trim()}”.</span>
            <button type="button" className="dm-pill dm-line dm-sm" onClick={() => setText('')}>Clear filter</button></div>
        )}
        <div className="dm-fxp-f dm-muted"><Swap className="dm-fxp-st">{foot === 'summary' ? summary(count(tree)) : sel}</Swap></div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- File explorer ---------- */
/* the project's files as a tree, with the ones the agent changed lettered M, A or D in their status colour and a dot on
   every folder that holds one. Its content is 16px from every edge, on shared columns (owner, 18 Nov): the top level's
   chevrons sit centred under the filter's search glyph, each level steps in 14px, and the Only changed button's glyph is
   centred over the letters' column; a row's hover and selection fill is the content's width, no wider. The card grows and
   shrinks with the folders it has open, smoothly (grow()), up to about eleven rows, then the tree scrolls with a thin
   scrollbar and its last row fades while there is more below. A filter that matches nothing shows the empty state */
.dm-fxp{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-2)}
/* the filter sits over a hairline and the path under one, in Soft and Blueprint (owner, 21 Nov: "soft and blueprint need
   divider lines"), each 8px from it, as the rows are spaced; Clean sets the path on its foot strip */
.dm-fxp-h{display:flex;gap:var(--dm-s-1);align-items:center;padding-bottom:var(--dm-s-2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-fxp-s{flex:1;min-width:0;display:flex;align-items:center;gap:var(--dm-s-2);height:32px;padding:0 10px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-fxp-s{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-fxp-s input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.dm-fxp-s:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-fxp-s input::placeholder{color:var(--dm-muted)}
/* Only changed: its box ends on the content's right edge, which puts its glyph over the letters' column */
.dm-fxp-ch{flex:none}
.dm-fxp-ch[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.dm-fxp .dm-fxp-tree{max-height:330px;overflow:auto;overscroll-behavior:contain}
.dm-fxp-tree.dm-more{-webkit-mask-image:linear-gradient(180deg,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(180deg,#000 calc(100% - 28px),transparent)}
/* a thin scrollbar in the style's hairline grey, not the browser's thick one */
.dm-fxp-tree{scrollbar-width:thin;scrollbar-color:var(--dm-rail) transparent}
.dm-fxp-tree::-webkit-scrollbar{width:8px;height:8px}
.dm-fxp-tree::-webkit-scrollbar-track{background:transparent}
.dm-fxp-tree::-webkit-scrollbar-thumb{background:var(--dm-rail);border:2px solid transparent;background-clip:padding-box;border-radius:var(--dm-r-pill)}
:root:not([data-style="soft"],[data-style="clean"]) .dm-fxp-tree:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::-webkit-scrollbar-thumb{border-radius:0}
.dm-fxp-n{display:flex;align-items:center;gap:6px;width:100%;height:30px;padding-right:var(--dm-s-2);border-radius:var(--dm-r-sm);font-size:13px;text-align:left;color:var(--dm-fg2);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-fxp-n:hover{background:var(--dm-row);color:var(--dm-fg)}}
/* rows fill the scrolling tree, which would cut an outside ring: theirs is drawn inside */
.dm-fxp-n:focus-visible{outline-offset:-2px}
.dm-fxp-n.dm-sel{background:var(--dm-sel);color:var(--dm-fg)}
.dm-fxp-n .dm-cv{width:14px;flex:none;display:grid;place-items:center;color:var(--dm-muted);transition:transform var(--dm-t) var(--dm-ease)}
.dm-fxp-n.dm-open .dm-cv{transform:rotate(90deg)}
.dm-fxp-n .dm-ic{color:var(--dm-muted);display:grid;flex:none}
.dm-fxp-n .dm-nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* the agent's change, as a letter in its status colour (4.5:1 on the row, its hover and its selection) */
/* the letters and the folders' dots end on one right edge, 8px inside the row's fill (owner, 21 Nov) */
.dm-fxp-n .dm-bd{flex:none;width:14px;font-size:11px;font-weight:500;line-height:1;text-align:right}
.dm-fxp-n .dm-bd.dm-M{color:var(--dm-warn)}.dm-fxp-n .dm-bd.dm-A{color:var(--dm-ok)}.dm-fxp-n .dm-bd.dm-D{color:var(--dm-bad)}
.dm-fxp-n.dm-D .dm-nm{text-decoration:line-through;color:var(--dm-muted)}
/* a folder that holds a change: a dot, in the letters' column */
.dm-fxp-n .dm-ag{flex:none;width:14px;display:grid;place-items:center end}
.dm-fxp-n .dm-ag::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent))}
.dm-fxp-k{display:grid;grid-template-rows:1fr;transition:grid-template-rows var(--dm-t) var(--dm-ease)}
.dm-fxp-k.dm-shut{grid-template-rows:0fr}
.dm-fxp-k>div{overflow:hidden;min-height:0}
.dm-fxp-f{padding-top:var(--dm-s-2);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-fxp-st{display:block;overflow:hidden;text-overflow:ellipsis}
/* no file matches the filter: the empty state (the lab's, lab/clean): a small sketch of a file list on a white card, a
   title, one muted line and Clear filter as an outline button */
.dm-fxp-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:16px 16px 12px;text-align:center}
.dm-fxp-em[hidden]{display:none}
.dm-fxp-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.dm-fxp-em>span:not(.dm-fxp-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted);overflow-wrap:anywhere}
.dm-fxp-em .dm-pill{margin-top:12px}
.dm-fxp-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.dm-fxp-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
.dm-fxp-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
:root:not([data-style="soft"],[data-style="clean"]) .dm-fxp-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-rail) 60%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) :is(.dm-fxp-em-art::before,.dm-fxp-em-art::after):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-fxp :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-fxp .dm-ib:active,:root [data-style="clean"] .dm-fxp .dm-ib:active,:root [data-style="clean"].dm-fxp .dm-ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): its content 16px in from each edge; rows and the field with 10px corners; the path under
   the tree on an off-white foot strip with a hairline over it, 16px under the last row */
:root[data-style="clean"] .dm-fxp.dm-panel,:root [data-style="clean"] .dm-fxp.dm-panel,:root [data-style="clean"].dm-fxp.dm-panel{padding:var(--dm-s-4) var(--dm-s-4) 0}
:root[data-style="clean"] .dm-fxp-h,:root [data-style="clean"] .dm-fxp-h,:root [data-style="clean"].dm-fxp-h{padding-bottom:0;border-bottom:0}
:root[data-style="clean"] .dm-fxp-n,:root [data-style="clean"] .dm-fxp-n,:root [data-style="clean"].dm-fxp-n{border-radius:10px}
:root[data-style="clean"] .dm-fxp-f,:root [data-style="clean"] .dm-fxp-f,:root [data-style="clean"].dm-fxp-f{margin:var(--dm-s-2) calc(-1 * var(--dm-s-4)) 0;padding:calc(var(--dm-strip-y) + 5px) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dm-fxp-ch,:root [data-style="clean"] .dm-fxp-ch,:root [data-style="clean"].dm-fxp-ch{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-fxp-ch[aria-pressed="true"],:root [data-style="clean"] .dm-fxp-ch[aria-pressed="true"],:root [data-style="clean"].dm-fxp-ch[aria-pressed="true"]{background:var(--dm-chip);color:var(--dm-fg);box-shadow:inset 0 0 0 1px var(--dm-hair)}
